<script setup>
import programs from '~/data/programs.json'
const props=defineProps({id:{type:Number,required:true}})
const program=computed(()=>programs.find(p=>p.id===props.id))
const next=computed(()=>programs[(programs.findIndex(p=>p.id===props.id)+1)%programs.length])
useSeoMeta({title:()=>program.value.title+' | Горски пътеки',description:()=>program.value.summary})
function isHeading(t){return /^(Какво ни очаква|За кого е|Защо гората|А приключението|Изберете своето преживяване|FOREST CHALLENGE|FOREST RESET|FOREST CREATE|Защо FOREST|Потопете се|Всеки ден е приключение|Повече от лагер|Преход, който разказва|Водени от човек|Готови ли сте)/.test(t)}
</script>
<template><main id="main"><section class="detail-hero"><div class="detail-intro"><NuxtLink class="breadcrumb" to="/#programs">← Всички пътеки</NuxtLink><p class="eyebrow">ПЪТЕКА 0{{ program.number }} · {{ program.audience }}</p><h1>{{ program.title }}</h1><p>{{ program.lead }}</p><a class="button lime" :href="'mailto:petsezona@gmail.com?subject='+encodeURIComponent('Запитване: '+program.title)">Попитайте за тази пътека <span>↗</span></a></div><img :src="program.image" :alt="program.title" class="detail-image"></section><section class="detail-body section"><article><template v-for="(text,i) in program.body" :key="i"><h2 v-if="isHeading(text)">{{ text }}</h2><p v-else>{{ text }}</p></template></article><aside class="trip-aside"><p class="eyebrow">ВАШАТА СЛЕДВАЩА КРАЧКА</p><h2>Да влезем<br>в гората?</h2><p>{{ program.audience }}.<br>Свържете се с нас за място, дата и програма според вашата група.</p><a class="button dark" href="tel:+359885850802">0885 850 802 ↗</a><a class="aside-email" :href="'mailto:petsezona@gmail.com?subject='+encodeURIComponent(program.title)">Изпратете запитване ↗</a><hr><p class="eyebrow">ВАШИЯТ ВОДАЧ</p><p>инж. Николай Адев<br>Лесовъд и планински водач</p></aside></section><section class="next-trail"><p class="eyebrow">ИМА ОЩЕ КАКВО ДА ОТКРИЕТЕ</p><NuxtLink :to="'/programs/'+next.id">{{ next.title }} <span>↗</span></NuxtLink></section><ContactSection/></main></template>
